CREATE TYPE public.app_role AS ENUM ('candidate','admin');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL DEFAULT 'candidate',UNIQUE(user_id,role)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$; CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,full_name text NOT NULL DEFAULT '' CHECK(length(full_name)<=100),country text NOT NULL DEFAULT '',city text NOT NULL DEFAULT '',category text NOT NULL DEFAULT 'Software development',education text NOT NULL DEFAULT '',experience integer NOT NULL DEFAULT 0 CHECK(experience BETWEEN 0 AND 70),biography text NOT NULL DEFAULT '' CHECK(length(biography)<=2000),portfolio text NOT NULL DEFAULT '' CHECK(length(portfolio)<=500),public_consent boolean NOT NULL DEFAULT false,passport_id text UNIQUE NOT NULL DEFAULT ('TP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.handle_new_talent() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'candidate'); RETURN NEW; END $$; CREATE TRIGGER on_talent_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_talent();
CREATE TABLE public.credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('Academic certificate','Transcript','Professional certificate','Employment reference','Alternative evidence')),filename text NOT NULL DEFAULT '' CHECK(length(filename)<=255),storage_path text,alternative_evidence text NOT NULL DEFAULT '' CHECK(length(alternative_evidence)<=3000),status text NOT NULL DEFAULT 'Pending review' CHECK(status IN ('Pending review','Under review','Verified','Additional evidence required','Not verified')),review_note text NOT NULL DEFAULT '' CHECK(length(review_note)<=2000),reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.credentials TO authenticated; GRANT ALL ON public.credentials TO service_role; ALTER TABLE public.credentials ENABLE ROW LEVEL SECURITY; CREATE POLICY credential_read ON public.credentials FOR SELECT TO authenticated USING(candidate_id=auth.uid() OR public.has_role(auth.uid(),'admin')); CREATE POLICY credential_submit ON public.credentials FOR INSERT TO authenticated WITH CHECK(candidate_id=auth.uid() AND status='Pending review' AND reviewed_by IS NULL AND reviewed_at IS NULL AND review_note='' AND (storage_path IS NULL OR storage_path LIKE auth.uid()::text||'/%')); CREATE POLICY credential_review ON public.credentials FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.stamp_review() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.reviewed_by=auth.uid(); NEW.reviewed_at=now(); NEW.candidate_id=OLD.candidate_id; NEW.storage_path=OLD.storage_path; RETURN NEW; END $$; CREATE TRIGGER record_review BEFORE UPDATE ON public.credentials FOR EACH ROW EXECUTE FUNCTION public.stamp_review();
CREATE TABLE public.assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),candidate_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,category text NOT NULL,score integer NOT NULL CHECK(score BETWEEN 0 AND 5),passed boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.assessments TO authenticated; GRANT ALL ON public.assessments TO service_role; ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY; CREATE POLICY assessment_read ON public.assessments FOR SELECT TO authenticated USING(candidate_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.submit_assessment(_category text,_answers integer[]) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s integer:=0; i integer; keys integer[]:=ARRAY[1,0,2,1,0]; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _category NOT IN ('Software development','Teaching','Nursing','Electrical work','Plumbing','Tailoring','Hospitality','Other professional skills') OR array_length(_answers,1) IS DISTINCT FROM 5 THEN RAISE EXCEPTION 'Invalid assessment'; END IF; FOR i IN 1..5 LOOP IF _answers[i] IS NULL OR _answers[i]<0 OR _answers[i]>2 THEN RAISE EXCEPTION 'Invalid answer'; END IF; IF _answers[i]=keys[i] THEN s:=s+1; END IF; END LOOP; INSERT INTO public.assessments(candidate_id,category,score,passed) VALUES(auth.uid(),_category,s,s>=4); RETURN jsonb_build_object('score',s,'passed',s>=4); END $$; REVOKE ALL ON FUNCTION public.submit_assessment(text,integer[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_assessment(text,integer[]) TO authenticated;
CREATE FUNCTION public.public_passport(_passport_id text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('full_name',p.full_name,'passport_id',p.passport_id,'category',p.category,'education',p.education,'experience',p.experience,'credentials',coalesce((SELECT jsonb_agg(jsonb_build_object('kind',c.kind,'status',c.status)) FROM public.credentials c WHERE c.candidate_id=p.id),'[]'::jsonb),'assessments',coalesce((SELECT jsonb_agg(jsonb_build_object('category',a.category,'score',a.score,'passed',a.passed,'created_at',a.created_at)) FROM public.assessments a WHERE a.candidate_id=p.id),'[]'::jsonb)) FROM public.profiles p WHERE p.passport_id=upper(_passport_id) AND p.public_consent AND EXISTS(SELECT 1 FROM public.assessments a WHERE a.candidate_id=p.id AND a.passed) $$; GRANT EXECUTE ON FUNCTION public.public_passport(text) TO anon,authenticated;
CREATE FUNCTION public.impact_stats() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('talents',(SELECT count(*) FROM public.profiles WHERE full_name<>''),'assessments',(SELECT count(*) FROM public.assessments),'verified',(SELECT count(*) FROM public.credentials WHERE status='Verified'),'bridging',(SELECT count(*) FROM public.profiles p WHERE EXISTS(SELECT 1 FROM public.assessments a WHERE a.candidate_id=p.id) AND NOT EXISTS(SELECT 1 FROM public.assessments a WHERE a.candidate_id=p.id AND a.passed)),'passports',(SELECT count(DISTINCT candidate_id) FROM public.assessments WHERE passed)) $$; GRANT EXECUTE ON FUNCTION public.impact_stats() TO anon,authenticated;
CREATE INDEX credentials_candidate_idx ON public.credentials(candidate_id); CREATE INDEX assessments_candidate_idx ON public.assessments(candidate_id);
CREATE POLICY private_document_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='credentials' AND (storage.foldername(name))[1]=auth.uid()::text); CREATE POLICY private_document_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='credentials' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE TABLE public.demo_talents(id text PRIMARY KEY,full_name text NOT NULL,category text NOT NULL,city text NOT NULL,education text NOT NULL,experience integer NOT NULL,score integer NOT NULL,status text NOT NULL); GRANT SELECT ON public.demo_talents TO anon,authenticated; GRANT ALL ON public.demo_talents TO service_role; ALTER TABLE public.demo_talents ENABLE ROW LEVEL SECURITY; CREATE POLICY demo_read ON public.demo_talents FOR SELECT TO anon,authenticated USING(true);
